

CREATE TABLE IF NOT EXISTS tools(slug TEXT PRIMARY KEY, name TEXT NOT NULL, price BIGINT, active INTEGER NOT NULL DEFAULT 1, metadata TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL,nickname TEXT NOT NULL,password TEXT, bio TEXT NOT NULL DEFAULT '',role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')),status TEXT NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS identities(provider TEXT,subject TEXT,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(provider,subject));
CREATE TABLE IF NOT EXISTS votes(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,slug TEXT NOT NULL REFERENCES tools(slug),user_id TEXT REFERENCES users(id) ON DELETE CASCADE,anonymous TEXT,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,UNIQUE(slug,user_id),UNIQUE(slug,anonymous),CHECK(user_id IS NOT NULL OR anonymous IS NOT NULL));
CREATE TABLE IF NOT EXISTS posts(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE SET NULL,title TEXT NOT NULL,body TEXT NOT NULL,board TEXT NOT NULL,tags TEXT NOT NULL DEFAULT '',tool_slug TEXT REFERENCES tools(slug),build TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'active',pinned INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS posts_board ON posts(status,board,created_at);
CREATE TABLE IF NOT EXISTS comments(id TEXT PRIMARY KEY,post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,user_id TEXT REFERENCES users(id) ON DELETE SET NULL,parent_id TEXT REFERENCES comments(id) ON DELETE CASCADE,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS comments_post ON comments(post_id,status);
CREATE TABLE IF NOT EXISTS reactions(user_id TEXT REFERENCES users(id) ON DELETE CASCADE,post_id TEXT REFERENCES posts(id) ON DELETE CASCADE,kind TEXT CHECK(kind IN ('like','bookmark')),PRIMARY KEY(user_id,post_id,kind));
CREATE TABLE IF NOT EXISTS bookmarks(user_id TEXT REFERENCES users(id) ON DELETE CASCADE,slug TEXT REFERENCES tools(slug),PRIMARY KEY(user_id,slug));
CREATE TABLE IF NOT EXISTS notifications(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,post_id TEXT REFERENCES posts(id) ON DELETE CASCADE,comment_id TEXT REFERENCES comments(id) ON DELETE CASCADE,label TEXT NOT NULL,is_read INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reports(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE SET NULL,target_type TEXT NOT NULL,target_id TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,target_type,target_id));
CREATE TABLE IF NOT EXISTS suggestions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE SET NULL,slug TEXT,title TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor TEXT REFERENCES users(id) ON DELETE SET NULL,action TEXT NOT NULL,target TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS waitlist(email TEXT PRIMARY KEY,token TEXT NOT NULL UNIQUE,consent TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,withdrawn_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS analytics(day DATE,event TEXT,path TEXT,count INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(day,event,path));
CREATE TABLE IF NOT EXISTS auth_tokens(token TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS uploads(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,mime TEXT NOT NULL,size INTEGER NOT NULL,storage TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);


CREATE TABLE IF NOT EXISTS consents(user_id TEXT REFERENCES users(id) ON DELETE CASCADE,policy TEXT NOT NULL,accepted_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,policy));
CREATE INDEX IF NOT EXISTS notifications_user ON notifications(user_id,is_read);
CREATE INDEX IF NOT EXISTS votes_slug ON votes(slug);

ALTER TABLE users ADD COLUMN email_verified_at TIMESTAMPTZ;
UPDATE users SET email_verified_at=CURRENT_TIMESTAMP WHERE id IN (SELECT user_id FROM identities);

CREATE UNIQUE INDEX users_email_case_insensitive ON users(lower(email));
CREATE UNIQUE INDEX users_nickname_case_insensitive ON users(lower(nickname));
CREATE UNIQUE INDEX waitlist_email_case_insensitive ON waitlist(lower(email));
CREATE TABLE IF NOT EXISTS mail_deliveries(campaign TEXT,email TEXT,created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(campaign,email));
